# 1. all claude.exe roots and their full descendant trees
$claudeRoots = $map.Values | Where-Object { $_.Name -match '^Claude(\.exe)?$' } |
               Select-Object -ExpandProperty Pid
$kill = Get-Descendants $claudeRoots $map
# 2. orphaned MCP-signature processes (parent claude already dead) not under a service
foreach ($p in $map.Values) {
  if ($p.Cmd -match $McpSig -and -not (Is-UnderService $p.Pid $map)) { [void]$kill.Add($p.Pid) }
}
# 3. self-protection: never kill this script's process or its ancestor chain
foreach ($a in Get-Ancestors $PID $map) { [void]$kill.Remove($a) }
return $kill

